package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;
@Entity @Table(name="succession_readiness_panel_assignment",uniqueConstraints=@UniqueConstraint(name="uk_succ_readiness_panel_member",columnNames={"agency_id","assessment_id","employee_no"}))
public class SuccessionReadinessPanelAssignment extends RspAuditedEntity{
 public enum Status{ASSIGNED,RECUSED,REPLACED}
 @Column(name="assessment_id",nullable=false,length=36)private String assessmentId;@Column(name="committee_member_id",nullable=false,length=36)private String committeeMemberId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="display_name",nullable=false,length=250)private String displayName;@Column(name="member_role",nullable=false,length=30)private String memberRole;@Column(name="voting_member",nullable=false)private boolean votingMember;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="conflict_declared",nullable=false)private boolean conflictDeclared;@Column(name="conflict_source",length=30)private String conflictSource;@Column(name="conflict_reason",length=2000)private String conflictReason;@Column(name="replacement_assignment_id",length=36)private String replacementAssignmentId;
 protected SuccessionReadinessPanelAssignment(){} public SuccessionReadinessPanelAssignment(String a,String assessment,SuccessionCommitteeMember m){super(a);assessmentId=requiredText(assessment,"assessmentId");committeeMemberId=m.getId();employeeNo=m.getEmployeeNo();displayName=m.getDisplayName();memberRole=m.getMemberRole().name();votingMember=m.isVotingMember();status=Status.ASSIGNED;}
 public void recuse(String source,String reason){if(status!=Status.ASSIGNED)throw new IllegalLifecycleTransitionException("Only an active panel assignment may be recused");conflictDeclared=true;conflictSource=requiredText(source,"conflictSource");conflictReason=requiredText(reason,"conflictReason");status=Status.RECUSED;}
 public void replaceWith(String replacement){if(status!=Status.RECUSED)throw new IllegalLifecycleTransitionException("Only a recused assignment may be replaced");replacementAssignmentId=requiredText(replacement,"replacementAssignmentId");status=Status.REPLACED;}
 public String getAssessmentId(){return assessmentId;}public String getCommitteeMemberId(){return committeeMemberId;}public String getEmployeeNo(){return employeeNo;}public String getDisplayName(){return displayName;}public String getMemberRole(){return memberRole;}public boolean isVotingMember(){return votingMember;}public Status getStatus(){return status;}public boolean isConflictDeclared(){return conflictDeclared;}public String getConflictSource(){return conflictSource;}public String getConflictReason(){return conflictReason;}public String getReplacementAssignmentId(){return replacementAssignmentId;}
}
